import { useState, useEffect } from "react";
import axios from "axios";
import "./EvaluatorDashboard.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import EvaluatorSidebar from "../components/EvaluatorSidebar";

const EvaluatorDashboard = () => {
  const [assignedGroups, setAssignedGroups] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:5000/api/assigned-groups/evaluator123")
      .then((response) => setAssignedGroups(response.data))
      .catch((error) => console.error("Error fetching groups:", error));
  }, []);

  return (
    <div className="dashboard-container">
      <Navbar />
      <div className="dashboard-layout">
        <EvaluatorSidebar />

        <main className="dashboard-main">
          <div className="hero-section">
            <h1>Welcome, Evaluator!</h1>
            <p>Review and evaluate student projects efficiently.</p>
          </div>

          <div className="dashboard-content">
            <div className="dashboard-section">
              <h2>Assigned Groups</h2>
              <div className="groups-list">
                {assignedGroups.length > 0 ? (
                  assignedGroups.map((group) => (
                    <div key={group._id} className="group-card">
                      <h3>{group.name}</h3>
                      <p>Project: {group.project}</p>
                      <p>Status: <strong>{group.status}</strong></p>
                      <button className="evaluate-btn">Evaluate Now</button>
                    </div>
                  ))
                ) : (
                  <p>No groups assigned yet.</p>
                )}
              </div>
            </div>
          </div>
        </main>
      </div>
      <Footer />
    </div>
  );
};

export default EvaluatorDashboard;
